//This code was generated by Claude and is used as a placeholder to ensure proper building and to test the R tree functionality

#include "RTree.h"
#include "Point.h"
#include <iostream>
#include <random>
#include <vector>
#include <string>

static double distSq(const Hospital& h, double lat, double lon) {
    double dLat = h.latitude - lat;
    double dLon = h.longitude - lon;
    return dLat * dLat + dLon * dLon;
}

int main() {
    // Random hospitals roughly covering the continental US
    std::mt19937 rng(42);
    std::uniform_real_distribution<double> latDist(25.0, 49.0);
    std::uniform_real_distribution<double> lonDist(-125.0, -67.0);

    std::vector<Hospital> hospitals;
    for (int i = 0; i < 500; i++) {
        Hospital h;
        h.name = "Hospital " + std::to_string(i);
        h.latitude = latDist(rng);
        h.longitude = lonDist(rng);
        hospitals.push_back(h);
    }

    RTree tree;
    tree.build(hospitals);

    // Compare the tree against brute force on 1000 random query points
    int mismatches = 0;
    for (int q = 0; q < 1000; q++) {
        double lat = latDist(rng);
        double lon = lonDist(rng);

        double bestBrute = distSq(hospitals[0], lat, lon);
        for (const Hospital& h : hospitals) {
            double d = distSq(h, lat, lon);
            if (d < bestBrute) bestBrute = d;
        }

        const Hospital* found = tree.nearest(lat, lon);
        if (found == nullptr || distSq(*found, lat, lon) != bestBrute) {
            mismatches++;
        }
    }

    std::cout << "Mismatches: " << mismatches << " out of 1000\n";
}